WITH parsed AS (SELECT id, currency, tier_limits, tier_prices, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT currency, COUNT(*) AS num_rows, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(currency = 'EUR') AS eur_events FROM parsed GROUP BY currency ORDER BY eur_events DESC NULLS LAST;
